CREATE TABLE organizations (
 id uuid PRIMARY KEY, name varchar(120) NOT NULL, deployment_mode text NOT NULL DEFAULT 'self_hosted' CHECK(deployment_mode='self_hosted'),
 active_jobs bigint NOT NULL DEFAULT 0 CHECK(active_jobs>=0), last_claim_at timestamptz NOT NULL DEFAULT 'epoch', created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE users (id uuid PRIMARY KEY,email text NOT NULL UNIQUE,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),disabled_at timestamptz);
CREATE TABLE organization_memberships (organization_id uuid REFERENCES organizations,user_id uuid REFERENCES users,role text NOT NULL CHECK(role='owner'),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,user_id),UNIQUE(organization_id),UNIQUE(user_id));
CREATE TABLE sessions (id uuid PRIMARY KEY,organization_id uuid NOT NULL,user_id uuid NOT NULL,token_hash bytea NOT NULL UNIQUE CHECK(octet_length(token_hash)=32),csrf_hash bytea NOT NULL CHECK(octet_length(csrf_hash)=32),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz,FOREIGN KEY(organization_id,user_id) REFERENCES organization_memberships,CHECK(expires_at>created_at));
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE projects (id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations,name varchar(120) NOT NULL CHECK(length(btrim(name))>0),created_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz,UNIQUE(organization_id,id));
CREATE INDEX projects_list ON projects(organization_id,created_at DESC,id DESC);
CREATE TABLE api_keys (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,name varchar(120) NOT NULL,prefix text NOT NULL,token_hash bytea NOT NULL UNIQUE,scope text NOT NULL DEFAULT 'events:write' CHECK(scope='events:write'),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,revoked_at timestamptz,FOREIGN KEY(organization_id,project_id) REFERENCES projects(organization_id,id));
CREATE TABLE endpoints (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,description varchar(500) NOT NULL DEFAULT '',paused boolean NOT NULL DEFAULT false,current_version_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,project_id,id),FOREIGN KEY(organization_id,project_id) REFERENCES projects(organization_id,id));
CREATE TABLE endpoint_versions (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,endpoint_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),url text NOT NULL CHECK(length(url)<=2048),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(endpoint_id,version),UNIQUE(organization_id,project_id,endpoint_id,id),FOREIGN KEY(organization_id,project_id,endpoint_id) REFERENCES endpoints(organization_id,project_id,id));
ALTER TABLE endpoints ADD FOREIGN KEY(organization_id,project_id,id,current_version_id) REFERENCES endpoint_versions(organization_id,project_id,endpoint_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE signing_keys (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,endpoint_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),ciphertext bytea NOT NULL,encryption_key_id text NOT NULL DEFAULT 'v1',activates_at timestamptz NOT NULL,retires_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(endpoint_id,version),UNIQUE(organization_id,project_id,endpoint_id,id),FOREIGN KEY(organization_id,project_id,endpoint_id) REFERENCES endpoints(organization_id,project_id,id),CHECK(retires_at IS NULL OR retires_at>activates_at));
CREATE TABLE events (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,type varchar(128) NOT NULL CHECK(length(btrim(type))>0),envelope_bytes bytea,payload_size integer NOT NULL CHECK(payload_size>=0),occurred_at timestamptz NOT NULL,accepted_at timestamptz NOT NULL,retention_at timestamptz,payload_purged_at timestamptz,UNIQUE(organization_id,project_id,id),FOREIGN KEY(organization_id,project_id) REFERENCES projects(organization_id,id));
CREATE INDEX events_list ON events(organization_id,project_id,accepted_at DESC,id DESC);
CREATE TABLE ingestion_requests (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,key varchar(128) NOT NULL,request_hash bytea NOT NULL CHECK(octet_length(request_hash)=32),event_id uuid NOT NULL,acceptance_response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days',UNIQUE(project_id,key),FOREIGN KEY(organization_id,project_id,event_id) REFERENCES events(organization_id,project_id,id));
CREATE TABLE deliveries (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,event_id uuid NOT NULL,endpoint_id uuid NOT NULL,endpoint_version_id uuid NOT NULL,generation integer NOT NULL CHECK(generation>0),state text NOT NULL CHECK(state IN('pending','in_flight','retry_wait','succeeded','failed','canceled')),attempts_count integer NOT NULL DEFAULT 0 CHECK(attempts_count BETWEEN 0 AND 6),next_attempt_at timestamptz,lease_token uuid,lease_until timestamptz,deadline_at timestamptz NOT NULL,last_error text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),terminal_at timestamptz,UNIQUE(organization_id,project_id,id),UNIQUE(event_id,endpoint_id,generation),FOREIGN KEY(organization_id,project_id,event_id) REFERENCES events(organization_id,project_id,id),FOREIGN KEY(organization_id,project_id,endpoint_id,endpoint_version_id) REFERENCES endpoint_versions(organization_id,project_id,endpoint_id,id),CHECK((state='in_flight')=(lease_token IS NOT NULL AND lease_until IS NOT NULL)),CHECK((state IN('succeeded','failed','canceled'))=(terminal_at IS NOT NULL)));
CREATE UNIQUE INDEX one_active_generation ON deliveries(event_id,endpoint_id) WHERE state IN('pending','in_flight','retry_wait');
CREATE INDEX deliveries_due ON deliveries(next_attempt_at,id) WHERE state IN('pending','retry_wait');
CREATE INDEX deliveries_expired ON deliveries(lease_until) WHERE state='in_flight';
CREATE TABLE delivery_attempts (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,delivery_id uuid NOT NULL,sequence integer NOT NULL CHECK(sequence BETWEEN 1 AND 6),lease_token uuid NOT NULL,signing_key_id uuid REFERENCES signing_keys,started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,outcome text NOT NULL CHECK(outcome IN('started','succeeded','failed','unknown')),http_status integer CHECK(http_status BETWEEN 100 AND 599),duration_ms bigint CHECK(duration_ms>=0),error_class varchar(120) NOT NULL DEFAULT '',response_preview text NOT NULL DEFAULT '' CHECK(octet_length(response_preview)<=4096),UNIQUE(delivery_id,sequence),FOREIGN KEY(organization_id,project_id,delivery_id) REFERENCES deliveries(organization_id,project_id,id));
CREATE TABLE replay_requests (id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,original_delivery_id uuid NOT NULL,key varchar(128) NOT NULL,request_hash bytea NOT NULL,new_delivery_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days',UNIQUE(organization_id,original_delivery_id,key),FOREIGN KEY(organization_id,project_id,original_delivery_id) REFERENCES deliveries(organization_id,project_id,id),FOREIGN KEY(organization_id,project_id,new_delivery_id) REFERENCES deliveries(organization_id,project_id,id));
CREATE TABLE usage_months (organization_id uuid REFERENCES organizations,month_start date NOT NULL,accepted_event_count bigint NOT NULL DEFAULT 0 CHECK(accepted_event_count>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,month_start));
CREATE TABLE system_capacity (key text PRIMARY KEY CHECK(key='delivery_queue'),active_jobs bigint NOT NULL DEFAULT 0 CHECK(active_jobs>=0),capacity bigint NOT NULL CHECK(capacity>0),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO system_capacity(key,capacity) VALUES('delivery_queue',100000);
CREATE TABLE rate_limit_buckets (scope_hash bytea NOT NULL,action text NOT NULL,window_start timestamptz NOT NULL,count integer NOT NULL CHECK(count>=0),expires_at timestamptz NOT NULL,PRIMARY KEY(scope_hash,action,window_start));
CREATE INDEX rate_expiry ON rate_limit_buckets(expires_at);
CREATE TABLE audit_entries (id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations,actor_user_id uuid REFERENCES users,actor_key_id uuid REFERENCES api_keys,action text NOT NULL,resource_type text NOT NULL,resource_id uuid NOT NULL,request_id text NOT NULL DEFAULT '',occurred_at timestamptz NOT NULL DEFAULT now(),metadata jsonb NOT NULL DEFAULT '{}');
CREATE INDEX audit_list ON audit_entries(organization_id,occurred_at DESC,id DESC);
